questions.q:
다음 C 프로그램의 출력 결과는?

#include <stdio.h>
int main(void) {
      int x = 100, y = 200;
      int* px = &x, *py = &y, *tmp;
      (*px) -= 10;
      (*py) += 50;
      tmp = px;
      px = py;
      py = tmp;
      (*px) += 50;
      (*py) -= 10;
      printf("x: %d, y: %d \n", x, y);
      return 0;
}
